window.BOOK={"key":"nukhba","app":"mutoon","lsk":"mutoon_nukhba_v1","title":"نخبة الفكر","unitWord":"فقرة","sub":"مصطلح الحديث: نخبة الفكر في مصطلح أهل الأثر · ابن حجر العسقلاني (ت ٨٥٢هـ) · ٢١ بابًا","source":"https://shamela.ws/book/616 (نخبة الفكر في مصطلح أهل الأثر، تحقيق د. عبد المحسن بن محمد القاسم، ط٢ ١٤٤١هـ، محقق على نسخ مقروءة على المصنف، مشكول بالكامل، الصفحات ٤٦–٧٣) · قوبل بـ: https://shamela.ws/book/1565 (نزهة النظر ت نور الدين عتر: متن النخبة مفردًا في آخره، مشكول، ص ١٤٦–١٥١) + https://shamela.ws/book/5940 (نخبة الفكر ط دار الحديث، مشكول جزئيًا) — see nukhba-sources.md","note":"النص المشكول بالكامل من تحقيق د. عبد المحسن القاسم على ثماني نسخ خطية بعضها مقروء على المصنف، وقوبل كلمةً كلمةً بسكربت على متن النخبة المفرد في آخر «نزهة النظر» بتحقيق نور الدين عتر، وعلى نشرة دار الحديث. أُبقي لفظ التحقيق في كل الفروق، وصُحّحت أخطاء شكل يسيرة، وكل ذلك في تقرير المصادر. عناوين الفصول تقسيم وصفي للتطبيق.","chapters":[{"id":"nu1","title":"مُقَدِّمَةُ الْمُصَنِّفِ","units":[{"id":"nu1_1","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ١","segs":[["matn","الحَمْدُ لِلَّهِ الَّذِي لَمْ يَزَلْ عَالِماً قَدِيراً، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ الَّذِي أَرْسَلَهُ إِلَى النَّاسِ بَشِيراً وَنَذِيراً، وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ تَسْلِيماً كَثِيراً. أَمَّا بَعْدُ:"]]},{"id":"nu1_2","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٢","segs":[["matn","فَإِنَّ التَّصَانِيفَ فِي اصْطِلَاحِ أَهْلِ الحَدِيثِ قَدْ كَثُرَتْ وَبُسِطَتْ وَاخْتُصِرَتْ، فَسَأَلَنِي بَعْضُ الإِخْوَانِ أَنْ أُلَخِّصَ لَهُ المُهِمَّ مِنْ ذَلِكَ، فَأَجَبْتُهُ إِلَى سُؤَالِهِ؛ رَجَاءَ الِانْدِرَاجِ فِي تِلْكَ المَسَالِكِ."]]}]},{"id":"nu2","title":"أَقْسَامُ الْخَبَرِ: الْمُتَوَاتِرُ وَالْآحَادُ","units":[{"id":"nu2_1","label":"أَقْسَامُ الْخَبَرِ: الْمُتَوَاتِرُ وَالْآحَادُ · ١","segs":[["matn","فَأَقُولُ: الخَبَرُ: إِمَّا أَنْ يَكُونَ لَهُ طُرُقٌ بِلَا عَدَدٍ مُعَيَّنٍ، أَوْ مَعَ حَصْرٍ بِمَا فَوْقَ الِاثْنَيْنِ، أَوْ بِهِمَا، أَوْ بِوَاحِدٍ: فَالأَوَّلُ: المُتَوَاتِرُ، المُفِيدُ لِلْعِلْمِ اليَقِينِيِّ بِشُرُوطِهِ. وَالثَّانِي: المَشْهُورُ، وَهُوَ المُسْتَفِيضُ عَلَى رَأْيٍ. وَالثَّالِثُ: العَزِيزُ، وَلَيْسَ شَرْطاً لِلصَّحِيحِ خِلَافاً لِمَنْ زَعَمَهُ."]]},{"id":"nu2_2","label":"أَقْسَامُ الْخَبَرِ: الْمُتَوَاتِرُ وَالْآحَادُ · ٢","segs":[["matn","وَالرَّابِعُ: الغَرِيبُ. وَكُلُّهَا سِوَى الأَوَّلِ آحَادٌ. وَفِيهَا المَقْبُولُ وَالمَرْدُودُ؛ لِتَوَقُّفِ الِاسْتِدْلَالِ بِهَا عَلَى البَحْثِ عَنْ أَحْوَالِ رُوَاتِهَا دُونَ الأَوَّلِ، وَقَدْ يَقَعُ فِيهَا مَا يُفِيدُ العِلْمَ النَّظَرِيَّ بِالقَرَائِنِ عَلَى المُخْتَارِ."]]}],"group":"الْخَبَرُ وَأَقْسَامُهُ"},{"id":"nu3","title":"الْغَرِيبُ: الْفَرْدُ الْمُطْلَقُ وَالْفَرْدُ النِّسْبِيُّ","units":[{"id":"nu3_1","label":"الْغَرِيبُ: الْفَرْدُ الْمُطْلَقُ وَالْفَرْدُ النِّسْبِيُّ · ١","segs":[["matn","ثُمَّ الغَرَابَةُ: إِمَّا أَنْ تَكُونَ فِي أَصْلِ السَّنَدِ، أَوْ لَا. فَالأَوَّلُ: الفَرْدُ المُطْلَقُ. وَالثَّانِي: الفَرْدُ النِّسْبِيُّ، وَيَقِلُّ إِطْلَاقُ الفَرْدِيَّةِ عَلَيْهِ."]]}],"group":"الْخَبَرُ وَأَقْسَامُهُ"},{"id":"nu4","title":"الصَّحِيحُ وَالْحَسَنُ","units":[{"id":"nu4_1","label":"الصَّحِيحُ وَالْحَسَنُ · ١","segs":[["matn","وَخَبَرُ الآحَادِ بِنَقْلِ عَدْلٍ تَامِّ الضَّبْطِ، مُتَّصِلَ السَّنَدِ، غَيْرَ مُعَلَّلٍ وَلَا شَاذٍّ: هُوَ الصَّحِيحُ لِذَاتِهِ. وَتَتَفَاوَتُ رُتَبُهُ بِتَفَاوُتِ هَذِهِ الأَوْصَافِ، وَمِنْ ثَمَّ قُدِّمَ صَحِيحُ البُخَارِيِّ، ثُمَّ مُسْلِمٍ، ثُمَّ شَرْطُهُمَا. فَإِنْ خَفَّ الضَّبْطُ: فَالحَسَنُ لِذَاتِهِ، وَبِكَثْرَةِ طُرُقِهِ يُصَحَّحُ."]]},{"id":"nu4_2","label":"الصَّحِيحُ وَالْحَسَنُ · ٢","segs":[["matn","فَإِنْ جُمِعَا فَلِلتَّرَدُّدِ فِي النَّاقِلِ حَيْثُ التَّفَرُّدُ، وَإِلَّا فَبِاعْتِبَارِ إِسْنَادَيْنِ."]]}],"group":"الْمَقْبُولُ"},{"id":"nu5","title":"زِيَادَةُ الثِّقَةِ، وَالْمَحْفُوظُ وَالشَّاذُّ، وَالْمَعْرُوفُ وَالْمُنْكَرُ","units":[{"id":"nu5_1","label":"زِيَادَةُ الثِّقَةِ، وَالْمَحْفُوظُ وَالشَّاذُّ، وَالْمَعْرُوفُ وَالْمُنْكَرُ · ١","segs":[["matn","وَزِيَادَةُ رَاوِيهِمَا مَقْبُولَةٌ مَا لَمْ تَقَعْ مُنَافِيَةً لِمَنْ هُوَ أَوْثَقُ. فَإِنْ خُولِفَ بِأَرْجَحَ: فَالرَّاجِحُ المَحْفُوظُ؛ وَمُقَابِلُهُ: الشَّاذُّ. وَمَعَ الضَّعْفِ: الرَّاجِحُ المَعْرُوفُ؛ وَمُقَابِلُهُ: المُنْكَرُ."]]}],"group":"الْمَقْبُولُ"},{"id":"nu6","title":"الْمُتَابِعُ وَالشَّاهِدُ وَالِاعْتِبَارُ","units":[{"id":"nu6_1","label":"الْمُتَابِعُ وَالشَّاهِدُ وَالِاعْتِبَارُ · ١","segs":[["matn","وَالفَرْدُ النِّسْبِيُّ: إِنْ وَافَقَهُ غَيْرُهُ: فَهُوَ المُتَابِعُ. وَإِنْ وُجِدَ مَتْنٌ يُشْبِهُهُ: فَهُوَ الشَّاهِدُ. وَتَتَبُّعُ الطُّرُقِ لِذَلِكَ: هُوَ الِاعْتِبَارُ."]]}],"group":"الْمَقْبُولُ"},{"id":"nu7","title":"الْمُحْكَمُ وَمُخْتَلِفُ الْحَدِيثِ وَالنَّاسِخُ وَالْمَنْسُوخُ","units":[{"id":"nu7_1","label":"الْمُحْكَمُ وَمُخْتَلِفُ الْحَدِيثِ وَالنَّاسِخُ وَالْمَنْسُوخُ · ١","segs":[["matn","ثُمَّ المَقْبُولُ: إِنْ سَلِمَ مِنَ المُعَارَضَةِ: فَهُوَ المُحْكَمُ. وَإِنْ عُورِضَ بِمِثْلِهِ: فَإِنْ أَمْكَنَ الجَمْعُ: فَهُوَ مُخْتَلِفُ الحَدِيثِ. أَوْ ثَبَتَ المُتَأَخِّرُ: فَهُوَ النَّاسِخُ، وَالآخَرُ المَنْسُوخُ، وَإِلَّا فَالتَّرْجِيحُ، ثُمَّ التَّوَقُّفُ."]]}],"group":"الْمَقْبُولُ"},{"id":"nu8","title":"الْمَرْدُودُ بِسَبَبِ السَّقْطِ","units":[{"id":"nu8_1","label":"الْمَرْدُودُ بِسَبَبِ السَّقْطِ · ١","segs":[["matn","ثُمَّ المَرْدُودُ: إِمَّا أَنْ يَكُونَ لِسَقْطٍ أَوْ طَعْنٍ. فَالسَّقْطُ: إِمَّا أَنْ يَكُونَ مِنْ مَبَادِئِ السَّنَدِ مِنْ مُصَنِّفٍ، أَوْ مِنْ آخِرِهِ بَعْدَ التَّابِعِيِّ، أَوْ غَيْرِ ذَلِكَ. فَالأَوَّلُ: المُعَلَّقُ. وَالثَّانِي: المُرْسَلُ. وَالثَّالِثُ: إِنْ كَانَ بِاثْنَيْنِ فَصَاعِداً مَعَ التَّوَالِي: فَهُوَ المُعْضَلُ، وَإِلَّا فَالمُنْقَطِعُ."]]},{"id":"nu8_2","label":"الْمَرْدُودُ بِسَبَبِ السَّقْطِ · ٢","segs":[["matn","ثُمَّ قَدْ يَكُونُ وَاضِحاً أَوْ خَفِيّاً: فَالأَوَّلُ: يُدْرَكُ بِعَدَمِ التَّلَاقِي، وَمِنْ ثَمَّ احْتِيجَ إِلَى التَّارِيخِ. وَالثَّانِي: المُدَلَّسُ، وَيَرِدُ بِصِيغَةٍ تَحْتَمِلُ اللُّقِيَّ: كَ«عَنْ»، وَ«قَالَ». وَكَذَا المُرْسَلُ الخَفِيُّ مِنْ مُعَاصِرٍ لَمْ يَلْقَ."]]}],"group":"الْمَرْدُودُ"},{"id":"nu9","title":"الْمَرْدُودُ بِسَبَبِ الطَّعْنِ","units":[{"id":"nu9_1","label":"الْمَرْدُودُ بِسَبَبِ الطَّعْنِ · ١","segs":[["matn","ثُمَّ الطَّعْنُ: إِمَّا أَنْ يَكُونَ لِكَذِبِ الرَّاوِي، أَوْ تُهَمَتِهِ بِذَلِكَ، أَوْ فُحْشِ غَلَطِهِ، أَوْ غَفْلَتِهِ، أَوْ فِسْقِهِ، أَوْ وَهْمِهِ، أَوْ مُخَالَفَتِهِ، أَوْ جَهَالَتِهِ، أَوْ بِدْعَتِهِ، أَوْ سُوءِ حِفْظِهِ. فَالأَوَّلُ: المَوْضُوعُ. وَالثَّانِي: المَتْرُوكُ. وَالثَّالِثُ: المُنْكَرُ عَلَى رَأْيٍ. وَكَذَا الرَّابِعُ وَالخَامِسُ."]]},{"id":"nu9_2","label":"الْمَرْدُودُ بِسَبَبِ الطَّعْنِ · ٢","segs":[["matn","ثُمَّ الوَهْمُ: إِنِ اطُّلِعَ عَلَيْهِ بِالقَرَائِنِ، وَجَمْعِ الطُّرُقِ: فَالمُعَلَّلُ."]]}],"group":"الْمَرْدُودُ"},{"id":"nu10","title":"الْمُخَالَفَةُ","units":[{"id":"nu10_1","label":"الْمُخَالَفَةُ · ١","segs":[["matn","ثُمَّ المُخَالَفَةُ: إِنْ كَانَتْ بِتَغْيِيرِ السِّيَاقِ: فَمُدْرَجُ الإِسْنَادِ. أَوْ بِدَمْجِ مَوْقُوفٍ بِمَرْفُوعٍ: فَمُدْرَجُ المَتْنِ. أَوْ بِتَقْدِيمٍ وَتَأْخِيرٍ: فَالمَقْلُوبُ. أَوْ بِزِيَادَةِ رَاوٍ: فَالمَزِيدُ فِي مُتَّصِلِ الأَسَانِيدِ. أَوْ بِإِبْدَالِهِ وَلَا مُرَجِّحَ: فَالمُضْطَرِبُ، وَقَدْ يَقَعُ الإِبْدَالُ عَمْداً امْتِحَاناً."]]},{"id":"nu10_2","label":"الْمُخَالَفَةُ · ٢","segs":[["matn","أَوْ بِتَغْيِيرِ حُرُوفٍ مَعَ بَقَاءِ السِّيَاقِ: فَالمُصَحَّفُ وَالمُحَرَّفُ. وَلَا يَجُوزُ تَعَمُّدُ تَغْيِيرِ المَتْنِ بِالنَّقْصِ وَالمُرَادِفِ، إِلَّا لِعَالِمٍ بِمَا يُحِيلُ المَعَانِيَ. فَإِنْ خَفِيَ المَعْنَى: احْتِيجَ إِلَى شَرْحِ الغَرِيبِ، وَبَيَانِ المُشْكِلِ."]]}],"group":"الْمَرْدُودُ"},{"id":"nu11","title":"الْجَهَالَةُ","units":[{"id":"nu11_1","label":"الْجَهَالَةُ · ١","segs":[["matn","ثُمَّ الجَهَالَةُ: وَسَبَبُهَا: أَنَّ الرَّاوِيَ قَدْ تَكْثُرُ نُعُوتُهُ فَيُذْكَرُ بِغَيْرِ مَا اشْتُهِرَ بِهِ لِغَرَضٍ، وَصَنَّفُوا فِيهِ المُوضِحَ. وَقَدْ يَكُونُ مُقِلّاً فَلَا يَكْثُرُ الأَخْذُ عَنْهُ، وَصَنَّفُوا فِيهِ الوُحْدَانَ."]]},{"id":"nu11_2","label":"الْجَهَالَةُ · ٢","segs":[["matn","أَوْ لَا يُسَمَّى اخْتِصَاراً، وَفِيهِ المُبْهَمَاتُ، وَلَا يُقْبَلُ المُبْهَمُ وَلَوْ أُبْهِمَ بِلَفْظِ التَّعْدِيلِ عَلَى الأَصَحِّ. فَإِنْ سُمِّيَ وَانْفَرَدَ وَاحِدٌ عَنْهُ: فَمَجْهُولُ العَيْنِ. أَوِ اثْنَانِ فَصَاعِداً، وَلَمْ يُوَثَّقْ: فَمَجْهُولُ الحَالِ، وَهُوَ المَسْتُورُ."]]}],"group":"الْمَرْدُودُ"},{"id":"nu12","title":"الْبِدْعَةُ","units":[{"id":"nu12_1","label":"الْبِدْعَةُ · ١","segs":[["matn","ثُمَّ البِدْعَةُ: إِمَّا بِمُكَفِّرٍ، أَوْ بِمُفَسِّقٍ. فَالأَوَّلُ: لَا يَقْبَلُ صَاحِبَهَا الجُمْهُورُ. وَالثَّانِي: يُقْبَلُ مَنْ لَمْ يَكُنْ دَاعِيَةً فِي الأَصَحِّ، إِلَّا إِنْ رَوَى مَا يُقَوِّي بِدْعَتَهُ فَيُرَدُّ عَلَى المُخْتَارِ، وَبِهِ صَرَّحَ الجُوزَجَانِيُّ شَيْخُ النَّسَائِيِّ."]]}],"group":"الْمَرْدُودُ"},{"id":"nu13","title":"سُوءُ الْحِفْظِ","units":[{"id":"nu13_1","label":"سُوءُ الْحِفْظِ · ١","segs":[["matn","ثُمَّ سُوءُ الحِفْظِ: إِنْ كَانَ لَازِماً فَالشَّاذُّ عَلَى رَأْيٍ، أَوْ طَارِئاً فَالمُخْتَلِطُ. وَمَتَى تُوبِعَ السَّيِّئُ الحِفْظِ بِمُعْتَبَرٍ وَكَذَا المَسْتُورُ، وَالمُرْسَلُ، وَالمُدَلَّسُ: صَارَ حَدِيثُهُمْ حَسَناً؛ لَا لِذَاتِهِ، بَلْ بِالمَجْمُوعِ."]]}],"group":"الْمَرْدُودُ"},{"id":"nu14","title":"الْمَرْفُوعُ وَالْمَوْقُوفُ وَالْمَقْطُوعُ","units":[{"id":"nu14_1","label":"الْمَرْفُوعُ وَالْمَوْقُوفُ وَالْمَقْطُوعُ · ١","segs":[["matn","ثُمَّ الإِسْنَادُ: إِمَّا أَنْ يَنْتَهِيَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَصْرِيحاً، أَوْ حُكْماً: مِنْ قَوْلِهِ، أَوْ فِعْلِهِ، أَوْ تَقْرِيرِهِ."]]},{"id":"nu14_2","label":"الْمَرْفُوعُ وَالْمَوْقُوفُ وَالْمَقْطُوعُ · ٢","segs":[["matn","أَوْ إِلَى الصَّحَابِيِّ كَذَلِكَ، وَهُوَ: مَنْ لَقِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُؤْمِناً بِهِ وَمَاتَ عَلَى الإِسْلَامِ وَلَوْ تَخَلَّلَتْ رِدَّةٌ فِي الأَصَحِّ. أَوْ إِلَى التَّابِعِيِّ، وَهُوَ: مَنْ لَقِيَ الصَّحَابِيَّ كَذَلِكَ. فَالأَوَّلُ: المَرْفُوعُ. وَالثَّانِي: المَوْقُوفُ."]]},{"id":"nu14_3","label":"الْمَرْفُوعُ وَالْمَوْقُوفُ وَالْمَقْطُوعُ · ٣","segs":[["matn","وَالثَّالِثُ: المَقْطُوعُ وَمَنْ دُونَ التَّابِعِيِّ فِيهِ: مِثْلُهُ. وَيُقَالُ لِلْأَخِيرَيْنِ: الأَثَرُ."]]}],"group":"الْإِسْنَادُ"},{"id":"nu15","title":"الْمُسْنَدُ، وَالْعُلُوُّ وَالنُّزُولُ","units":[{"id":"nu15_1","label":"الْمُسْنَدُ، وَالْعُلُوُّ وَالنُّزُولُ · ١","segs":[["matn","وَالمُسْنَدُ: مَرْفُوعُ صَحَابِيٍّ بِسَنَدٍ ظَاهِرُهُ الِاتِّصَالُ. فَإِنْ قَلَّ عَدَدُهُ: فَإِمَّا أَنْ يَنْتَهِيَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ إِلَى إِمَامٍ ذِي صِفَةٍ عَلِيَّةٍ كَ«شُعْبَةَ». فَالأَوَّلُ: العُلُوُّ المُطْلَقُ. وَالثَّانِي: العُلُوُّ النِّسْبِيُّ."]]},{"id":"nu15_2","label":"الْمُسْنَدُ، وَالْعُلُوُّ وَالنُّزُولُ · ٢","segs":[["matn","وَفِيهِ المُوَافَقَةُ؛ وَهِيَ: الوُصُولُ إِلَى شَيْخِ أَحَدِ المُصَنِّفِينَ مِنْ غَيْرِ طَرِيقِهِ. وَالبَدَلُ؛ وَهُوَ: الوُصُولُ إِلَى شَيْخِ شَيْخِهِ كَذَلِكَ. وَالمُسَاوَاةُ؛ وَهِيَ: اسْتِوَاءُ عَدَدِ الإِسْنَادِ مِنَ الرَّاوِي إِلَى آخِرِهِ، مَعَ إِسْنَادِ أَحَدِ المُصَنِّفِينَ. وَالمُصَافَحَةُ؛ وَهِيَ: الِاسْتِوَاءُ مَعَ تِلْمِيذِ ذَلِكَ المُصَنِّفِ. وَيُقَابِلُ العُلُوَّ بِأَقْسَامِهِ: النُّزُولُ."]]}],"group":"الْإِسْنَادُ"},{"id":"nu16","title":"رِوَايَةُ الْأَقْرَانِ وَالْأَكَابِرِ، وَالْمُهْمَلُ، وَالْمُسَلْسَلُ","units":[{"id":"nu16_1","label":"رِوَايَةُ الْأَقْرَانِ وَالْأَكَابِرِ، وَالْمُهْمَلُ، وَالْمُسَلْسَلُ · ١","segs":[["matn","فَإِنْ تَشَارَكَ الرَّاوِي وَمَنْ رَوَى عَنْهُ فِي السِّنِّ وَاللُّقِيِّ فَهُوَ: الأَقْرَانُ. وَإِنْ رَوَى كُلٌّ مِنْهُمَا عَنِ الآخَرِ: فَالمُدَبَّجُ. وَإِنْ رَوَى عَمَّنْ دُونَهُ: فَالأَكَابِرُ عَنِ الأَصَاغِرِ، وَمِنْهُ: الآبَاءُ عَنِ الأَبْنَاءِ؛ وَفِي عَكْسِهِ كَثْرَةٌ، وَمِنْهُ: مَنْ رَوَى عَنْ أَبِيهِ عَنْ جَدِّهِ."]]},{"id":"nu16_2","label":"رِوَايَةُ الْأَقْرَانِ وَالْأَكَابِرِ، وَالْمُهْمَلُ، وَالْمُسَلْسَلُ · ٢","segs":[["matn","وَإِنِ اشْتَرَكَ اثْنَانِ عَنْ شَيْخٍ، وَتَقَدَّمَ مَوْتُ أَحَدِهِمَا؛ فَهُوَ: السَّابِقُ وَاللَّاحِقُ. وَإِنْ رَوَى عَنِ اثْنَيْنِ مُتَّفِقَيِ الِاسْمِ، وَلَمْ يَتَمَيَّزَا: فَبِاخْتِصَاصِهِ بِأَحَدِهِمَا يَتَبَيَّنُ المُهْمَلُ. وَإِنْ جَحَدَ الشَّيْخُ مَرْوِيَّهُ جَزْماً: رُدَّ، أَوِ احْتِمَالاً: قُبِلَ فِي الأَصَحِّ، وَفِيهِ: مَنْ حَدَّثَ وَنَسِيَ."]]},{"id":"nu16_3","label":"رِوَايَةُ الْأَقْرَانِ وَالْأَكَابِرِ، وَالْمُهْمَلُ، وَالْمُسَلْسَلُ · ٣","segs":[["matn","وَإِنِ اتَّفَقَ الرُّوَاةُ فِي صِيَغِ الأَدَاءِ، أَوْ غَيْرِهَا مِنَ الحَالَاتِ؛ فَهُوَ المُسَلْسَلُ."]]}],"group":"الْإِسْنَادُ"},{"id":"nu17","title":"صِيَغُ الْأَدَاءِ","units":[{"id":"nu17_1","label":"صِيَغُ الْأَدَاءِ · ١","segs":[["matn","وَصِيَغُ الأَدَاءِ: «سَمِعْتُ» وَ«حَدَّثَنِي»، ثُمَّ «أَخْبَرَنِي»، وَ«قَرَأْتُ عَلَيْهِ»، ثُمَّ «قُرِئَ عَلَيْهِ وَأَنَا أَسْمَعُ»، ثُمَّ «أَنْبَأَنِي»، ثُمَّ «نَاوَلَنِي»، ثُمَّ «شَافَهَنِي»، ثُمَّ «كَتَبَ إِلَيَّ»، ثُمَّ «عَنْ» وَنَحْوُهَا. فَالأَوَّلَانِ: لِمَنْ سَمِعَ وَحْدَهُ مِنْ لَفْظِ الشَّيْخِ، فَإِنْ جُمِعَ فَمَعَ غَيْرِهِ."]]},{"id":"nu17_2","label":"صِيَغُ الْأَدَاءِ · ٢","segs":[["matn","وَأَوَّلُهَا: أَصْرَحُهَا وَأَرْفَعُهَا فِي الإِمْلَاءِ. وَالثَّالِثُ، وَالرَّابِعُ: لِمَنْ قَرَأَ بِنَفْسِهِ. فَإِنْ جُمِعَ: فَهُوَ كَالخَامِسِ. وَالإِنْبَاءُ: بِمَعْنَى الإِخْبَارِ، إِلَّا فِي عُرْفِ المُتَأَخِّرِينَ؛ فَهُوَ لِلْإِجَازَةِ كَ«عَنْ». وَعَنْعَنَةُ المُعَاصِرِ مَحْمُولَةٌ عَلَى السَّمَاعِ إِلَّا مِنَ المُدَلِّسِ، وَقِيلَ: يُشْتَرَطُ ثُبُوتُ لِقَائِهِمَا وَلَوْ مَرَّةً وَهُوَ المُخْتَارُ."]]},{"id":"nu17_3","label":"صِيَغُ الْأَدَاءِ · ٣","segs":[["matn","وَأَطْلَقُوا المُشَافَهَةَ فِي الإِجَازَةِ المُتَلَفَّظِ بِهَا، وَالمُكَاتَبَةَ فِي الإِجَازَةِ المَكْتُوبِ بِهَا. وَاشْتَرَطُوا فِي صِحَّةِ المُنَاوَلَةِ: اقْتِرَانَهَا بِالإِذْنِ بِالرِّوَايَةِ وَهِيَ أَرْفَعُ أَنْوَاعِ الإِجَازَةِ."]]},{"id":"nu17_4","label":"صِيَغُ الْأَدَاءِ · ٤","segs":[["matn","وَكَذَا اشْتَرَطُوا: الإِذْنَ فِي الوِجَادَةِ، وَالوَصِيَّةِ بِالكِتَابِ، وَالإِعْلَامِ، وَإِلَّا فَلَا عِبْرَةَ بِذَلِكَ كَالإِجَازَةِ العَامَّةِ، وَلِلْمَجْهُولِ وَالمَعْدُومِ عَلَى الأَصَحِّ فِي جَمِيعِ ذَلِكَ."]]}],"group":"الْإِسْنَادُ"},{"id":"nu18","title":"الْمُتَّفِقُ وَالْمُفْتَرِقُ، وَالْمُؤْتَلِفُ وَالْمُخْتَلِفُ، وَالْمُتَشَابِهُ","units":[{"id":"nu18_1","label":"الْمُتَّفِقُ وَالْمُفْتَرِقُ، وَالْمُؤْتَلِفُ وَالْمُخْتَلِفُ، وَالْمُتَشَابِهُ · ١","segs":[["matn","ثُمَّ الرُّوَاةُ إِنِ اتَّفَقَتْ أَسْمَاؤُهُمْ، وَأَسْمَاءُ آبَائِهِمْ فَصَاعِداً، وَاخْتَلَفَتْ أَشْخَاصُهُمْ: فَهُوَ المُتَّفِقُ وَالمُفْتَرِقُ. وَإِنِ اتَّفَقَتِ الأَسْمَاءُ خَطّاً، وَاخْتَلَفَتْ نُطْقاً: فَهُوَ المُؤْتَلِفُ وَالمُخْتَلِفُ."]]},{"id":"nu18_2","label":"الْمُتَّفِقُ وَالْمُفْتَرِقُ، وَالْمُؤْتَلِفُ وَالْمُخْتَلِفُ، وَالْمُتَشَابِهُ · ٢","segs":[["matn","وَإِنِ اتَّفَقَتِ الأَسْمَاءُ وَاخْتَلَفَتِ الآبَاءُ، أَوْ بِالعَكْسِ: فَهُوَ المُتَشَابِهُ، وَكَذَا إِنْ وَقَعَ ذَلِكَ الِاتِّفَاقُ فِي الِاسْمِ وَاسْمِ الأَبِ، وَالِاخْتِلَافُ فِي النِّسْبَةِ."]]},{"id":"nu18_3","label":"الْمُتَّفِقُ وَالْمُفْتَرِقُ، وَالْمُؤْتَلِفُ وَالْمُخْتَلِفُ، وَالْمُتَشَابِهُ · ٣","segs":[["matn","وَيَتَرَكَّبُ مِنْهُ وَمِمَّا قَبْلَهُ أَنْوَاعٌ؛ مِنْهَا: أَنْ يَحْصُلَ الِاتِّفَاقُ أَوِ الِاشْتِبَاهُ، إِلَّا فِي حَرْفٍ أَوْ حَرْفَيْنِ، أَوْ بِالتَّقْدِيمِ وَالتَّأْخِيرِ، وَنَحْوِ ذَلِكَ."]]}],"group":"الْإِسْنَادُ"},{"id":"nu19","title":"خَاتِمَةٌ: طَبَقَاتُ الرُّوَاةِ، وَمَرَاتِبُ الْجَرْحِ وَالتَّعْدِيلِ","units":[{"id":"nu19_1","label":"خَاتِمَةٌ: طَبَقَاتُ الرُّوَاةِ، وَمَرَاتِبُ الْجَرْحِ وَالتَّعْدِيلِ · ١","segs":[["matn","وَمِنَ المُهِمِّ: مَعْرِفَةُ طَبَقَاتِ الرُّوَاةِ وَمَوَالِيدِهِمْ، وَوَفَيَاتِهِمْ، وَبُلْدَانِهِمْ، وَأَحْوَالِهِمْ تَعْدِيلاً، وَتَجْرِيحاً، وَجَهَالَةً. وَمَرَاتِبِ الجَرْحِ: وَأَسْوَأُهَا: الوَصْفُ بِأَفْعَلَ؛ كَ«أَكْذَبِ النَّاسِ»، ثُمَّ «دَجَّالٌ»، أَوْ «وَضَّاعٌ»، أَوْ «كَذَّابٌ». وَأَسْهَلُهَا: «لَيِّنٌ»، أَوْ «سَيِّئُ الحِفْظِ»، أَوْ «فِيهِ أَدْنَى مَقَالٍ»."]]},{"id":"nu19_2","label":"خَاتِمَةٌ: طَبَقَاتُ الرُّوَاةِ، وَمَرَاتِبُ الْجَرْحِ وَالتَّعْدِيلِ · ٢","segs":[["matn","وَمَرَاتِبِ التَّعْدِيلِ: وَأَرْفَعُهَا: الوَصْفُ بِأَفْعَلَ؛ كَ«أَوْثَقِ النَّاسِ». ثُمَّ مَا تَأَكَّدَ بِصِفَةٍ أَوْ صِفَتَيْنِ كَ«ثِقَةٍ ثِقَةٍ»، أَوْ «ثِقَةٍ حَافِظٍ». وَأَدْنَاهَا: مَا أَشْعَرَ بِالقُرْبِ مِنْ أَسْهَلِ التَّجْرِيحِ؛ كَ«شَيْخٍ». وَتُقْبَلُ التَّزْكِيَةُ مِنْ عَارِفٍ بِأَسْبَابِهَا، وَلَوْ مِنْ وَاحِدٍ عَلَى الأَصَحِّ."]]},{"id":"nu19_3","label":"خَاتِمَةٌ: طَبَقَاتُ الرُّوَاةِ، وَمَرَاتِبُ الْجَرْحِ وَالتَّعْدِيلِ · ٣","segs":[["matn","وَالجَرْحُ مُقَدَّمٌ عَلَى التَّعْدِيلِ إِنْ صَدَرَ مُبَيَّناً مِنْ عَارِفٍ بِأَسْبَابِهِ، فَإِنْ خَلَا عَنْ تَعْدِيلٍ قُبِلَ مُجْمَلاً عَلَى المُخْتَارِ."]]}],"group":"الْخَاتِمَةُ"},{"id":"nu20","title":"الْكُنَى وَالْأَسْمَاءُ وَالْأَلْقَابُ وَالْأَنْسَابُ","units":[{"id":"nu20_1","label":"الْكُنَى وَالْأَسْمَاءُ وَالْأَلْقَابُ وَالْأَنْسَابُ · ١","segs":[["matn","وَمَعْرِفَةُ كُنَى المُسَمَّيْنَ، وَأَسْمَاءِ المُكَنَّيْنَ. وَمَنِ اسْمُهُ كُنْيَتُهُ. وَمَنْ كَثُرَتْ كُنَاهُ أَوْ نُعُوتُهُ. وَمَنْ وَافَقَتْ كُنْيَتُهُ اسْمَ أَبِيهِ، أَوْ بِالعَكْسِ، أَوْ كُنْيَتُهُ كُنْيَةَ زَوْجَتِهِ. وَمَنْ نُسِبَ إِلَى غَيْرِ أَبِيهِ، أَوْ إِلَى غَيْرِ مَا يَسْبِقُ إِلَى الفَهْمِ."]]},{"id":"nu20_2","label":"الْكُنَى وَالْأَسْمَاءُ وَالْأَلْقَابُ وَالْأَنْسَابُ · ٢","segs":[["matn","وَمَنِ اتَّفَقَ اسْمُهُ وَاسْمُ أَبِيهِ وَجَدِّهِ، أَوْ وَاسْمُ شَيْخِهِ وَشَيْخِ شَيْخِهِ فَصَاعِداً. وَمَنِ اتَّفَقَ اسْمُ شَيْخِهِ وَالرَّاوِي عَنْهُ. وَمَعْرِفَةُ الأَسْمَاءِ المُجَرَّدَةِ وَالمُفْرَدَةِ، وَكَذَا الكُنَى، وَالأَلْقَابُ، وَالأَنْسَابُ. وَتَقَعُ إِلَى القَبَائِلِ، وَالأَوْطَانِ بِلَاداً، أَوْ ضِيَاعاً وَسِكَكاً، وَمُجَاوَرَةً. وَإِلَى الصَّنَائِعِ وَالحِرَفِ."]]},{"id":"nu20_3","label":"الْكُنَى وَالْأَسْمَاءُ وَالْأَلْقَابُ وَالْأَنْسَابُ · ٣","segs":[["matn","وَيَقَعُ فِيهَا الِاتِّفَاقُ وَالِاشْتِبَاهُ كَالأَسْمَاءِ. وَقَدْ تَقَعُ أَلْقَاباً. وَمَعْرِفَةُ أَسْبَابِ ذَلِكَ."]]}],"group":"الْخَاتِمَةُ"},{"id":"nu21","title":"الْمَوَالِي، وَآدَابُ الشَّيْخِ وَالطَّالِبِ، وَسَبَبُ الْحَدِيثِ","units":[{"id":"nu21_1","label":"الْمَوَالِي، وَآدَابُ الشَّيْخِ وَالطَّالِبِ، وَسَبَبُ الْحَدِيثِ · ١","segs":[["matn","وَمَعْرِفَةُ المَوَالِي مِنْ أَعْلَى، وَمِنْ أَسْفَلَ، بِالرِّقِّ، أَوْ بِالحِلْفِ. وَمَعْرِفَةُ الإِخْوَةِ وَالأَخَوَاتِ. وَمَعْرِفَةُ آدَابِ الشَّيْخِ وَالطَّالِبِ. وَسِنِّ التَّحَمُّلِ وَالأَدَاءِ. وَصِفَةِ كِتَابَةِ الحَدِيثِ، وَعَرْضِهِ، وَسَمَاعِهِ، وَإِسْمَاعِهِ، وَالرِّحْلَةِ فِيهِ. وَتَصْنِيفِهِ عَلَى المَسَانِيدِ، أَوِ الأَبْوَابِ، أَوِ العِلَلِ، أَوِ الأَطْرَافِ."]]},{"id":"nu21_2","label":"الْمَوَالِي، وَآدَابُ الشَّيْخِ وَالطَّالِبِ، وَسَبَبُ الْحَدِيثِ · ٢","segs":[["matn","وَمَعْرِفَةُ سَبَبِ الحَدِيثِ، وَقَدْ صَنَّفَ فِيهِ بَعْضُ شُيُوخِ القَاضِي أَبِي يَعْلَى ابْنِ الفَرَّاءِ. وَصَنَّفُوا فِي غَالِبِ هَذِهِ الأَنْوَاعِ. وَهِيَ نَقْلٌ مَحْضٌ، ظَاهِرَةُ التَّعْرِيفِ، مُسْتَغْنِيَةٌ عَنِ التَّمْثِيلِ؛ فَلْتُرَاجَعْ لَهَا مَبْسُوطَاتُهَا. وَاللَّهُ المُوَفِّقُ وَالهَادِي، لَا إِلَهَ إِلَّا هُوَ."]]}],"group":"الْخَاتِمَةُ"}],"basmala":"بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ"};
